<?php require 'config/db.php';require 'includes/auth.php';require_login();$page_title='Emergency Alerts';if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['ADMIN','OPERATOR']);check_csrf();$action=$_POST['action']??'';if($action==='create'){$s=$pdo->prepare('INSERT INTO alerts(message,level,status,incident_id) VALUES(?,?,?,?)');$iid=$_POST['incident_id']!==''?(int)$_POST['incident_id']:null;$s->execute([trim($_POST['message']),$_POST['level'],'Open',$iid]);audit($pdo,'Alert created',$_POST['message']);$_SESSION['flash']='Alert created.';}elseif($action==='status'){$s=$pdo->prepare('UPDATE alerts SET status=? WHERE id=?');$s->execute([$_POST['status'],(int)$_POST['id']]);audit($pdo,'Alert status changed','Alert #'.(int)$_POST['id'].' to '.$_POST['status']);$_SESSION['flash']='Alert status updated.';}header('Location:alerts.php');exit;}$inc=$pdo->query("SELECT id,incident_type,location FROM incidents WHERE status!='Resolved' ORDER BY id DESC")->fetchAll();$rows=$pdo->query('SELECT a.*,i.incident_type FROM alerts a LEFT JOIN incidents i ON i.id=a.incident_id ORDER BY a.id DESC')->fetchAll();require 'includes/header.php';?><section class="panel"><?php if(can_write()):?><h2>Create Alert</h2><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><input class="full" name="message" placeholder="Alert message" required><select name="level"><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select><select name="incident_id"><option value="">No linked incident</option><?php foreach($inc as $i):?><option value="<?=$i['id']?>">#<?=$i['id']?> <?=e($i['incident_type'])?> — <?=e($i['location'])?></option><?php endforeach;?></select><button>Create Alert</button></form><?php endif;?><div class="tablewrap"><table><tr><th>Message</th><th>Level</th><th>Incident</th><th>Status</th><th>Time</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['message'])?></td><td><span class="badge <?=strtolower($r['level'])?>"><?=e($r['level'])?></span></td><td><?=e($r['incident_type']??'—')?></td><td><?=e($r['status'])?></td><td><?=e($r['alert_time'])?></td><td><?php if(can_write()):?><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option <?=$r['status']==='Open'?'selected':''?>>Open</option><option <?=$r['status']==='Acknowledged'?'selected':''?>>Acknowledged</option><option <?=$r['status']==='Closed'?'selected':''?>>Closed</option></select><button class="smallbtn">Update</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section><?php require 'includes/footer.php';?>
